// Cross-implementation vectors generated by crypto/ztv_crypto (python) via gen_vectors.py.
import { describe, expect, it } from "vitest";
import V from "./vectors.json";
import { b64u, b64uDecode, canonicalJson, canonicalJsonString, equalBytes, sha256, utf8 } from "../crypto/encoding";
import { aadForChunk, decryptChunk, encryptChunk, importDek, nonceForChunk } from "../crypto/chunks";
import { leafHash, merkleRoot } from "../crypto/merkle";
import { hkdfInfo, unwrapDek, wrapDek } from "../crypto/wrap";
import { importAgreementKey, importSigningKey, detectWebCryptoCurves } from "../crypto/curves";
import { openPrivateKeys, sealPrivateKeys, importUserKeys } from "../crypto/keys";
import { certFingerprint, signGrant, signManifest, verifyGrant, verifyManifest, verifyUserCert, type Manifest, type Grant, type UserCert } from "../crypto/sign";
import { jwkThumbprint } from "../crypto/device";
import { accessTokenHash, htuFromUrl } from "../crypto/dpop";

describe("encoding", () => {
  it("canonical json matches python", () => {
    expect(b64u(canonicalJson(V.canonical_json.obj))).toBe(V.canonical_json.bytes_b64u);
    expect(() => canonicalJsonString({ a: 1.5 })).toThrow();
  });
  it("b64u roundtrip", () => {
    const b = new Uint8Array([0, 255, 1, 254, 62, 63]);
    expect(b64uDecode(b64u(b))).toEqual(b);
  });
});

describe("chunks", () => {
  it("aad bytes", () => {
    expect(b64u(aadForChunk(V.aad.file_id, V.aad.version, V.aad.index, V.aad.final))).toBe(V.aad.aad_b64u);
  });
  it("nonce bytes", () => {
    expect(b64u(nonceForChunk(b64uDecode(V.nonce.prefix_b64u), V.nonce.index))).toBe(V.nonce.nonce_b64u);
  });
  it("AES-GCM chunks encrypt/decrypt identical to python", async () => {
    const c = V.chunks;
    const dek = await importDek(b64uDecode(c.dek_b64u));
    const prefix = b64uDecode(c.prefix_b64u);
    const n = c.plain_b64u.length;
    for (let i = 0; i < n; i++) {
      const ct = await encryptChunk(dek, prefix, c.file_id, c.version, i, b64uDecode(c.plain_b64u[i]), i === n - 1);
      expect(b64u(ct)).toBe(c.ct_b64u[i]);
      const pt = await decryptChunk(dek, prefix, c.file_id, c.version, i, b64uDecode(c.ct_b64u[i]), i === n - 1);
      expect(b64u(pt)).toBe(c.plain_b64u[i]);
    }
    // tamper -> abort
    const bad = b64uDecode(c.ct_b64u[0]);
    bad[0] ^= 1;
    await expect(decryptChunk(dek, prefix, c.file_id, c.version, 0, bad, false)).rejects.toThrow();
    // wrong final flag -> abort
    await expect(decryptChunk(dek, prefix, c.file_id, c.version, 0, b64uDecode(c.ct_b64u[0]), true)).rejects.toThrow();
  });
});

describe("merkle", () => {
  it("leaves and root of ciphertext chunks", async () => {
    const cts = V.chunks.ct_b64u.map(b64uDecode);
    for (let i = 0; i < cts.length; i++) expect(b64u(await leafHash(cts[i]))).toBe(V.chunks.leaves_b64u[i]);
    expect(b64u(await merkleRoot(cts))).toBe(V.chunks.merkle_root_b64u);
  });
  it("5-leaf tree with odd promotion", async () => {
    expect(b64u(await merkleRoot(V.merkle_5.chunks_b64u.map(b64uDecode)))).toBe(V.merkle_5.root_b64u);
  });
});

describe("wrap", () => {
  it("hkdf info", () => {
    expect(b64u(hkdfInfo(V.hkdf_info.file_id, V.hkdf_info.version))).toBe(V.hkdf_info.info_b64u);
  });
  it("unwraps a python-wrapped DEK and round-trips a TS-wrapped one", async () => {
    const w = V.wrap;
    const sk = await importAgreementKey(b64uDecode(w.recipient_sk_pkcs8_b64u));
    expect(b64u(sk.publicKey)).toBe(w.recipient_pk_b64u);
    const dek = await unwrapDek(w.record, sk, w.file_id, w.version);
    expect(b64u(dek)).toBe(w.dek_b64u);
    const rec2 = await wrapDek(dek, sk.publicKey, w.file_id, w.version);
    expect(b64uDecode(rec2.wrapped).length).toBe(40);
    expect(b64u(await unwrapDek(rec2, sk, w.file_id, w.version))).toBe(w.dek_b64u);
    await expect(unwrapDek(rec2, sk, w.file_id, w.version + 1)).rejects.toThrow();
  });
});

describe("sealed key blob", () => {
  it("opens a python-sealed blob (small argon2 params) and derives the same public keys", async () => {
    const b = V.blob;
    const keys = await openPrivateKeys(b.blob as never, b.passphrase);
    expect(keys.encPk).toBe(b.enc_pk_b64u);
    expect(keys.sigPk).toBe(b.sig_pk_b64u);
    await expect(openPrivateKeys(b.blob as never, "wrong")).rejects.toThrow();
  });
  it("seal in TS -> open in TS", async () => {
    const b = V.blob;
    const sk = { enc_sk: b64uDecode(b.enc_sk_pkcs8_b64u), sig_sk: b64uDecode(b.sig_sk_pkcs8_b64u) };
    const blob = await sealPrivateKeys(sk, "pw", { m: 1024, t: 1, p: 1 });
    expect(blob.kdf.m).toBe(1024);
    const keys = await openPrivateKeys(blob, "pw");
    expect(keys.encPk).toBe(b.enc_pk_b64u);
  });
});

describe("signatures", () => {
  it("verifies a python-signed manifest and grant; TS signatures verify with the same pk", async () => {
    const pk = b64uDecode(V.manifest.owner_sig_pk_b64u);
    expect(await verifyManifest(V.manifest.signed as Manifest, pk)).toBe(true);
    expect(await verifyManifest({ ...(V.manifest.signed as Manifest), size: 1 }, pk)).toBe(false);
    expect(await verifyGrant(V.grant.signed as Grant, pk)).toBe(true);
    const keys = await importUserKeys({ enc_sk: b64uDecode(V.blob.enc_sk_pkcs8_b64u), sig_sk: b64uDecode(V.blob.sig_sk_pkcs8_b64u) });
    const { signature: _s, ...body } = V.manifest.signed as Manifest;
    const signed = await signManifest(body as Manifest, keys.sig);
    // Ed25519 is deterministic: identical signature to python
    expect(signed.signature).toBe(V.manifest.signed.signature);
    const { signature: _g, ...gbody } = V.grant.signed as Grant;
    expect((await signGrant(gbody as Grant, keys.sig)).signature).toBe(V.grant.signed.signature);
  });
  it("verifies a python-issued cert against the root and computes the fingerprint", async () => {
    const root = b64uDecode(V.cert.root_pk_b64u);
    const cert = V.cert.cert as UserCert;
    expect(await verifyUserCert(cert, root, { expectedUserId: cert.user_id })).toBe(true);
    expect(await verifyUserCert(cert, root, { expectedUserId: "other" })).toBe(false);
    expect(await verifyUserCert({ ...cert, username: "mallory" }, root)).toBe(false);
    expect(await verifyUserCert(cert, b64uDecode(V.manifest.owner_sig_pk_b64u))).toBe(false);
    expect(await certFingerprint(b64uDecode(cert.enc_pk), b64uDecode(cert.sig_pk))).toBe(V.cert.fingerprint);
  });
  it("signing key import reports backend", async () => {
    const k = await importSigningKey(b64uDecode(V.blob.sig_sk_pkcs8_b64u));
    const d = await detectWebCryptoCurves();
    expect(k.backend).toBe(d.ed ? "webcrypto" : "noble");
  });
});

describe("dpop", () => {
  it("thumbprint + ath + htu", async () => {
    expect(await jwkThumbprint(V.dpop.jwk)).toBe(V.dpop.jkt);
    expect(await accessTokenHash("abc")).toBe(V.dpop.ath_of_abc);
    expect(htuFromUrl("HTTPS://LocalHost:8443/api/files?x=1#f")).toBe("https://localhost:8443/api/files");
  });
  it("audit genesis", async () => {
    expect(equalBytes(await sha256(utf8("ZTV-AUDIT-GENESIS")), b64uDecode(V.audit.genesis_b64u))).toBe(true);
  });
});
